gN_(){return"\u0625\u063a\u0644\u0627\u0642 \u0641\u062a\u0631\u0629 \u0628\u062d\u064a\u062b \u0644\u0627 \u064a\u0645\u0643\u0646 \u062a\u0631\u062d\u064a\u0644 \u0623\u0648 \u0625\u0644\u063a\u0627\u0621 \u0623\u064a \u0634\u064a\u0621 \u0642\u0628\u0644\u0647\u0627"},
gMI(){return'\u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u0644\u0648\u0633\u0645 \u0627\u0644\u0645\u0635\u0631\u0648\u0641\u0627\u062a \u0628\u0647\u0627\u060c \u0644\u062a\u0642\u0631\u064a\u0631 "\u0627\u0644\u0625\u0646\u0641\u0627\u0642 \u062d\u0633\u0628 \u0627\u0644\u0642\u0633\u0645"'},
gML(){return"\u0633\u062c\u0644 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0628\u0645\u0631\u0648\u0631 \u0627\u0644\u0648\u0642\u062a \u2014 \u064a\u0645\u0644\u0623 \u0645\u0633\u062a\u0646\u062f\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u0627\u062a \u0627\u0644\u0623\u062c\u0646\u0628\u064a\u0629 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0648\u064a\u063a\u0630\u064a \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062a\u0642\u064a\u064a\u0645"},
gMZ(){return"\u062d\u064a\u062b \u0643\u0627\u0646\u062a \u0627\u0644\u0646\u0642\u062f\u064a\u0629 \u0648\u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0648\u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u0623\u062e\u0631\u0649 \u0642\u0628\u0644 \u062a\u0631\u0627\u0632\u0648"},
