gMA(){return"\u0645\u0642\u0627\u0645\u0627\u062a \u0627\u0648\u0631 \u06af\u0648\u062f\u0627\u0645\u0648\u06ba \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645 \u06a9\u0631\u06cc\u06ba"},
gN4(){return"\u0645\u0627\u0644\u06a9\u060c \u0627\u06a9\u0627\u0624\u0646\u0679\u0646\u0679\u060c \u06cc\u0627 \u0627\u0633\u0679\u0627\u0641/\u0688\u06cc\u0644\u06cc\u0648\u0631\u06cc \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u0679\u06cc\u0645 \u0645\u0645\u0628\u0631\u0632 \u0634\u0627\u0645\u0644 \u06a9\u0631\u06cc\u06ba"},
gMS(){return"\u067e\u0631\u0627\u0646\u06d2 \u0633\u0627\u0641\u0679 \u0648\u06cc\u0626\u0631 \u0633\u06d2 \u062f\u0631\u0622\u0645\u062f \u06a9\u0631\u06cc\u06ba"},
gMT(){return"Manager.io \u0633\u06d2 \u0627\u067e\u0646\u0627 \u0688\u06cc\u0679\u0627 \u0644\u0627\u0626\u06cc\u06ba"},
gMU(){return"\u0679\u06cc\u0645\u067e\u0644\u06cc\u0679\u0633 \u0633\u06d2 \u062f\u0631\u0622\u0645\u062f \u06a9\u0631\u06cc\u06ba"},
gMV(){return"\u0627\u06cc\u06a9 CSV \u0679\u06cc\u0645\u067e\u0644\u06cc\u0679 \u0688\u0627\u0624\u0646 \u0644\u0648\u0688 \u06a9\u0631\u06cc\u06ba \u0627\u0648\u0631 \u06a9\u0633\u06cc \u0628\u06be\u06cc \u067e\u0631\u0627\u0646\u06d2 \u0633\u0633\u0679\u0645 \u0633\u06d2 \u0688\u06cc\u0679\u0627 \u062f\u0631\u0622\u0645\u062f \u06a9\u0631\u06cc\u06ba"},
gRb(){return"\u0628\u06cc\u06a9 \u0627\u067e \u0627\u0648\u0631 \u0633\u0646\u06a9 \u06a9\u0648 \u0628\u0631\u0627\u06c1 \u0631\u0627\u0633\u062a \u0641\u0627\u0626\u0644 \u062a\u06a9 \u0631\u0633\u0627\u0626\u06cc \u062f\u0631\u06a9\u0627\u0631 \u06c1\u06d2 \u0627\u0648\u0631 \u06cc\u06c1 \u0627\u0628\u06be\u06cc \u0648\u06cc\u0628 \u0628\u0644\u0688 \u0645\u06cc\u06ba \u062f\u0633\u062a\u06cc\u0627\u0628 \u0646\u06c1\u06cc\u06ba\u06d4 \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0645\u0648\u0628\u0627\u0626\u0644 \u06cc\u0627 \u0688\u06cc\u0633\u06a9 \u0679\u0627\u067e \u0627\u06cc\u067e \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u06cc\u06ba\u06d4"},
gTd(){return"\u06a9\u0645\u067e\u0646\u06cc \u067e\u0631\u0648\u0641\u0627\u0626\u0644"},
