gSJ(){return"\u067e\u0631\u0646\u0679 \u0634\u062f\u06c1 \u0627\u0646\u0648\u0627\u0626\u0633\u0632 \u067e\u0631 \u0628\u06cc\u0646\u06a9 \u062a\u0641\u0635\u06cc\u0644\u0627\u062a \u0628\u0627\u06a9\u0633 \u06a9\u0648 \u0645\u06a9\u0645\u0644 \u0637\u0648\u0631 \u067e\u0631 \u0686\u06be\u067e\u0627\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062e\u0627\u0644\u06cc \u0686\u06be\u0648\u0691 \u062f\u06cc\u06ba\u06d4"},
gST(){return"\u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u06a9\u06cc \u0634\u06a9\u0644"},
gSS(){return"\u06c1\u0631 \u067e\u0631\u0646\u0679 \u0634\u062f\u06c1 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u067e\u0631 \u0644\u0627\u06af\u0648 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u2014 \u0627\u0646\u0648\u0627\u0626\u0633\u060c \u06a9\u0648\u0679\u06cc\u0634\u0646\u060c \u062e\u0631\u06cc\u062f\u0627\u0631\u06cc \u0622\u0631\u0688\u0631\u06d4"},
gT5(){return"\u0631\u0642\u0645 \u0627\u0644\u0641\u0627\u0638 \u0645\u06cc\u06ba \u062f\u06a9\u06be\u0627\u0626\u06cc\u06ba"},
gT6(){return"\u0628\u06cc\u0646\u06a9 \u062a\u0641\u0635\u06cc\u0644\u0627\u062a \u0628\u0627\u06a9\u0633 \u062f\u06a9\u06be\u0627\u0626\u06cc\u06ba"},
gGS(){return"\u0645\u062d\u0641\u0648\u0638 \u06c1\u0648 \u06af\u06cc\u0627\u06d4"},
gJX(){return"\u067e\u06cc\u0679\u06cc \u06a9\u06cc\u0634"},
ga0r(){return"\u0627\u0628\u06be\u06cc \u062a\u06a9 \u06a9\u0648\u0626\u06cc \u067e\u06cc\u0679\u06cc \u06a9\u06cc\u0634 \u0641\u0646\u0688 \u0646\u06c1\u06cc\u06ba \u06c1\u06d2\u06d4 \u0686\u06be\u0648\u0679\u06d2 \u0631\u0648\u0632\u0645\u0631\u06c1 \u0627\u062e\u0631\u0627\u062c\u0627\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u0622\u067e \u062c\u0648 \u06c1\u0631 \u06a9\u06cc\u0634 \u0628\u0627\u06a9\u0633 \u0631\u06a9\u06be\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u06cc\u06a9 \u0634\u0627\u0645\u0644 \u06a9\u0631\u06cc\u06ba\u06d4"},
